WITH valid AS (SELECT *, DATE_TRUNC('week', event_time) AS event_time_period, COALESCE(page, 'UNKNOWN') AS page_filled FROM web_events WHERE duration_sec >= 288), enriched AS (SELECT *, LAST_VALUE(page, TRUE) OVER (ORDER BY event_time_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_page, SUM(duration_sec) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec FROM valid WHERE event_type = 'page_view'), ranked AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY event_type, session_id ORDER BY event_time DESC, id) = 1), ranked_web_events AS (SELECT id, session_id, event_time, event_time_period, last_known_page, running_duration_sec FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time_period DESC NULLS FIRST, id) AS rn FROM ranked) ranked WHERE rn = 1), enriched_web_events AS (SELECT *, AVG(running_duration_sec) OVER (PARTITION BY YEAR(event_time), session_id ORDER BY running_duration_sec, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS running_duration_sec_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY YEAR(event_time_period) ORDER BY event_time_period, id) AS event_seq FROM ranked_web_events), totals AS (SELECT session_id, MIN(running_duration_sec_avg_6_prior) AS min_running_duration_sec_avg_6_prior, MIN(running_duration_sec) AS min_running_duration_sec, COUNT(DISTINCT session_id) AS distinct_session_ids, PERCENTILE_APPROX(running_duration_sec, ARRAY(0.25, 0.5, 0.75)) AS running_duration_sec_quartiles, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, COUNT(*) AS num_rows FROM enriched_web_events GROUP BY CUBE (session_id)) SELECT s.session_id, s.min_running_duration_sec, s.distinct_session_ids, s.running_duration_sec_quartiles, s.num_rows, (SELECT MIN(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS min_web_event_duration_sec FROM totals s ORDER BY num_rows NULLS LAST;
